<section class="lm-auth-page" aria-labelledby="login-title"><div class="lm-auth-card"><div class="p-4 p-sm-5"><div class="lm-eyebrow mb-3">Welcome back</div><h1 id="login-title" class="lm-auth-title h2 fw-bold mb-2">Sign in to Learmingo</h1><p class="lm-muted mb-4">Continue your learning journey from where you left off.</p><?php if ($error): ?><div class="alert alert-danger rounded-3" role="alert"><?= e($error) ?></div><?php endif; ?><form method="post" action="/login"><div class="mb-3"><label class="form-label fw-semibold" for="login-email">Email address</label><input id="login-email" class="form-control" type="email" name="email" required autocomplete="email" placeholder="you@example.com"></div><div class="mb-4"><div class="d-flex justify-content-between align-items-center"><label class="form-label fw-semibold" for="login-password">Password</label></div><div class="lm-password-wrap"><input id="login-password" class="form-control" type="password" name="password" required autocomplete="current-password" placeholder="Enter your password"><button type="button" class="lm-password-toggle" data-password-toggle="login-password" aria-controls="login-password" aria-pressed="false">Show</button></div></div><?= csrf_field() ?><button class="btn btn-primary w-100 fw-semibold" type="submit">Sign in</button></form><p class="lm-muted text-center small mt-4 mb-0">New to Learmingo? <a class="fw-semibold text-decoration-none" href="/register">Create an account</a></p></div></div></section>
